<script>
(() => {
    // Show the builders of the chosen project only.
    const project = document.getElementById('construction-project'), field = document.getElementById('construction-builder-field'), builder = document.getElementById('construction-builder');
    const sync = () => {
        field.hidden = !project.value;
        builder.querySelectorAll('option[data-project]').forEach(o => { o.hidden = o.dataset.project !== project.value; });
        const chosen = builder.options[builder.selectedIndex];
        if (chosen && chosen.dataset.project && chosen.dataset.project !== project.value) builder.value = '';
    };
    project.addEventListener('change', sync); sync();
})();
</script>
