const partyInput=document.querySelector('#party-input'),partyHint=document.querySelector('#party-hint'),staffBalance=document.querySelector('#staff-balance'),referenceLabel=document.querySelector('#reference-label'),referenceHint=document.querySelector('#reference-hint');
const transactionDescription=document.querySelector('#transaction-description');
const trackInventory=document.querySelector('#track-inventory'),stockStoreField=document.querySelector('#stock-store-field'),inventoryStore=stockStoreField.querySelector('select'),stockUnitField=document.querySelector('#stock-unit-field'),inventoryUnit=document.querySelector('#inventory-unit'),stockLocationField=document.querySelector('#stock-location-field'),inventoryLocation=document.querySelector('#inventory-location');
const quantityField=document.querySelector('#quantity-field'),unitPriceField=document.querySelector('#unit-price-field');
const previewFrom=document.querySelector('#preview-from'),previewTo=document.querySelector('#preview-to'),previewAmount=document.querySelector('#preview-amount');
function options(select,values,selected=''){select.innerHTML='';values.forEach(value=>select.add(new Option(value,value,value===selected,value===selected)));}
function syncCostCentres(){const selected=department.options[department.selectedIndex],code=selected?.dataset.code||'',items=costCentres[code]||[];options(costCentre,items,'{{ old('cost_centre') }}');costCentre.disabled=!items.length;if(!items.length)costCentre.add(new Option(department.value?'No units configured':'Choose department first',''));}
function syncSupplier(){const purchase=category.value==='purchase',staff=category.value==='staff_payment',banking=category.value==='banking',equity=category.value==='capital_and_equity';partyLabel.textContent=purchase?'Supplier':(banking?'Destination account':definitions[category.value].party);partyInput.placeholder=purchase?'Type or choose a supplier':(staff?'Choose a staff member':(banking?'Type destination, e.g. Cash on Hand':(equity?'Enter owner or shareholder name':'Type or choose a customer')));partyHint.textContent=purchase?'Choose a listed supplier or type a new supplier name directly.':'Choose an existing name or type a new one.';partyInput.required=purchase||staff||banking||equity;if(equity)partyInput.removeAttribute('list');else partyInput.setAttribute('list',purchase?'finance-supplier-list':(staff?'finance-staff-list':(banking?'banking-account-list':'finance-customer-list')));}
function syncStock(){const animalPurchase=category.value==='purchase'&&account.value==='Stocking';const tracked=category.value==='purchase'&&Number(quantity.value)>0&&!animalPurchase;trackInventory.value=tracked?'1':'0';stockStoreField.hidden=!tracked;stockUnitField.hidden=!tracked;stockLocationField.hidden=!tracked;inventoryStore.required=tracked;inventoryUnit.required=tracked;inventoryLocation.required=tracked;const hint=document.querySelector('#animal-purchase-hint');if(hint)hint.hidden=!animalPurchase;}
function syncSubAccount(){const items=category.value==='purchase'?(purchaseSubAccounts[account.value]||[]):[];subAccountField.hidden=!items.length;subAccount.disabled=!items.length;subAccount.required=items.length>0;if(items.length)options(subAccount,items,'{{ old('sub_account') }}');}
function syncSettlement(){const purchase=category.value==='purchase',staff=category.value==='staff_payment',equity=category.value==='capital_and_equity',items=purchase?(purchaseSettlementAccounts[account.value]||[]):farmAccounts;options(paymentAccount,items,'{{ old('account') }}');paymentAccountLabel.textContent=purchase?'Settlement account':(staff?'Pay from (farm account)':(equity?'Farm cash / bank account':'Payment / receiving account'));settlementHint.textContent=purchase?'Choose paid now, credit/payable, or prepayment.':(staff?'This is the farm account the payment leaves.':(equity?'The farm account receiving or paying the money.':''));}
function syncPaymentMethod(){if(paymentMethod.value==='in_kind'){if(!Array.from(paymentAccount.options).some(option=>option.value==='In-kind / Barter Clearing'))paymentAccount.add(new Option('In-kind / Barter Clearing','In-kind / Barter Clearing'));paymentAccount.value='In-kind / Barter Clearing';paymentAccount.disabled=true;settlementHint.textContent='Describe what was received or given and enter its fair UGX value.';}else paymentAccount.disabled=false;}
function syncEquity(){if(category.value!=='capital_and_equity')return;const reserve=account.value==='Reserve Transfer';methodField.hidden=reserve;paymentAccountField.hidden=reserve;paymentAccount.required=!reserve;partyInput.required=true;settlementHint.textContent=reserve?'No cash account is required for an internal reserve transfer.':'Choose the farm account affected by this owner/shareholder transaction.';}
function syncAccount(){const items=definitions[category.value].groups[group.value]||[];options(account,items.length?items:['Other / Unclassified'],'{{ old('entry_account') }}');syncSubAccount();syncSettlement();syncEquity();syncStock();}
function syncRelated(){dueField.hidden=category.value!=='revenue'||receiptKind.value!=='customer_payment';billField.hidden=category.value!=='purchase'||paymentKind.value!=='supplier_bill';due.disabled=dueField.hidden;bill.disabled=billField.hidden;}
function syncBill(){if(bill.disabled||!bill.value){amount.removeAttribute('max');return}const selected=bill.options[bill.selectedIndex];if(selected?.dataset.supplier)partyInput.value=selected.dataset.supplier;if(selected?.dataset.balance){amount.value=selected.dataset.balance;amount.max=selected.dataset.balance;amount.placeholder='Up to UGX '+Number(selected.dataset.balance).toLocaleString();}if(transactionDescription)transactionDescription.value='Payment toward supplier bill '+(selected?.dataset.reference||'without reference')+': '+(selected?.dataset.description||'supplier balance');fetch('/finance/payables/'+bill.value+'/details').then(response=>response.ok?response.json():null).then(details=>{if(!details)return;if(details.quantity){quantity.value=details.quantity;if(selected?.dataset.balance)unitPrice.value=(Number(selected.dataset.balance)/Number(details.quantity)).toFixed(2);}if(details.unit)inventoryUnit.value=details.unit;}).catch(()=>{});}
function sync(){const entry=definitions[category.value],selected=group.value||'{{ old('account_group') }}';options(group,Object.keys(entry.groups),selected);const equity=category.value==='capital_and_equity',prepayment=category.value==='customer_prepayment';groupLabel.textContent=equity?'Transaction class':'Account group';accountLabel.textContent=equity?'Capital / equity action':'Account / item';partyLabel.textContent=entry.party;syncSupplier();syncStock();const purchase=category.value==='purchase',revenue=category.value==='revenue',banking=category.value==='banking',cash=['money_received','money_paid'].includes(entry.ledger_type),noQuantity=banking||equity||prepayment||category.value==='staff_payment';quantityField.hidden=noQuantity;unitPriceField.hidden=noQuantity;quantity.disabled=noQuantity;unitPrice.disabled=noQuantity;referenceLabel.textContent=purchase?'Voucher Number':((revenue||prepayment)?'Receipt / reference number':'Reference number');referenceHint.textContent=prepayment?'Enter the receipt, bank, or mobile-money reference for the advance received.':(purchase?'The same voucher number may be used for several expenses covered by that voucher.':(banking?'Use the withdrawal slip, deposit slip, or bank transaction reference.':(equity?'Use the deposit slip, payment reference, board resolution, or supporting document.':'Enter the source document number.')));methodField.hidden=!cash&&!equity;paymentAccountField.hidden=!cash&&!equity;paymentAccount.required=cash||equity;receiptField.hidden=!revenue;paymentKindField.hidden=!purchase;syncAccount();syncRelated();updatePreview();}
function calculate(){if(quantity.value&&unitPrice.value!=='')amount.value=(Number(quantity.value)*Number(unitPrice.value)).toFixed(2);}
function updateStaffBalance(){const salaryWithdrawal=category.value==='staff_payment'&&account.value==='Salary Withdrawal';staffBalance.hidden=!salaryWithdrawal;if(!salaryWithdrawal)return;const available=Number(staffBalances[partyInput.value]||0);staffBalance.textContent='Available salary: UGX '+available.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});staffBalance.classList.toggle('is-empty',available<=0);amount.max=available>0?available:'';if(available<=0)staffBalance.textContent+=' — withdrawal will be blocked';}
function syncRecipientAccount(){const staff=category.value==='staff_payment',details=staffPaymentDetails[partyInput.value]||{},method=paymentMethod.value;recipientAccountField.hidden=!staff||method==='cash'||!method;recipientAccount.required=staff&&(method==='bank'||['mobile_money','mtn_merchant','airtel_merchant'].includes(method));recipientAccount.readOnly=staff&&method==='bank';recipientDestinations.innerHTML='';if(!staff)return;if(method==='bank'){recipientAccountLabel.textContent='Staff bank account';recipientAccount.value=details.bank||'';recipientAccountHint.textContent=details.bank?'Registered by HR.':'No bank account is registered for this worker.';}else if(['mobile_money','mtn_merchant','airtel_merchant'].includes(method)){recipientAccountLabel.textContent='Staff mobile money number';(details.phones||[]).forEach(phone=>recipientDestinations.add(new Option(phone,phone)));if(details.mobile_money&&!recipientAccount.value)recipientAccount.value=details.mobile_money;recipientAccountHint.textContent='Choose a registered number or type a new mobile money number.';}else if(method==='cash'){recipientAccount.value='Cash collected by '+(partyInput.value||'staff member');recipientAccountHint.textContent='';}}
function updatePreview(){syncRecipientAccount();const entry=definitions[category.value],settlement=paymentMethod.value==='in_kind'?'In-kind / Barter Clearing':(paymentAccount.value||'Choose an account'),item=account.value||'Choose an account',party=partyInput.value||entry.party,destination=category.value==='staff_payment'&&recipientAccount.value?party+' — '+recipientAccount.value:party;if(entry.ledger_type==='money_received'){previewFrom.textContent=party;previewTo.textContent=settlement;}else if(entry.ledger_type==='money_paid'){previewFrom.textContent=settlement;previewTo.textContent=destination||item;}else{previewFrom.textContent=item;previewTo.textContent=party;}previewAmount.textContent='UGX '+Number(amount.value||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});updateStaffBalance();}
document.querySelector('#finance-entry').addEventListener('submit',()=>{document.querySelector('#ledger-account').value=paymentAccountField.hidden?account.value:(paymentMethod.value==='in_kind'?'In-kind / Barter Clearing':paymentAccount.value);paymentAccount.disabled=false;recipientAccount.readOnly=false;});department.addEventListener('change',syncCostCentres);category.addEventListener('change',()=>{recipientAccount.value='';sync();syncPaymentMethod();syncBill();updatePreview();});group.addEventListener('change',()=>{syncAccount();updatePreview();});account.addEventListener('change',()=>{syncSubAccount();syncSettlement();syncEquity();syncStock();syncPaymentMethod();updatePreview();});paymentMethod.addEventListener('change',()=>{recipientAccount.value='';syncPaymentMethod();updatePreview();});paymentAccount.addEventListener('change',updatePreview);partyInput.addEventListener('change',()=>{recipientAccount.value='';updatePreview();});partyInput.addEventListener('input',updatePreview);recipientAccount.addEventListener('input',updatePreview);amount.addEventListener('input',updatePreview);receiptKind.addEventListener('change',syncRelated);paymentKind.addEventListener('change',()=>{syncRelated();syncBill();});bill.addEventListener('change',()=>{syncBill();updatePreview();});quantity.addEventListener('input',()=>{calculate();syncStock();updatePreview();});unitPrice.addEventListener('input',()=>{calculate();updatePreview();});syncCostCentres();sync();syncPaymentMethod();syncBill();updatePreview();
</script>
